221:   if (!zombieAsset.root || !window.THREE.SkeletonUtils) return false;
222:   const replacement = THREE.SkeletonUtils.clone(zombieAsset.root);
223:   replacement.traverse((part) => {
224:     if (!part.isMesh) return;
225:     part.castShadow = true;
226:     part.receiveShadow = true;
227:     const cloneMaterial = (material) => {
228:       const instance = material.clone();
229:       if (instance.color) instance.color.multiplyScalar(1.12);
230:       if (instance.color && zombie.variant.tint !== 0xffffff) instance.color.multiply(new THREE.Color(zombie.variant.tint));
231:       if (instance.emissive && instance.emissive.getHex() !== 0) instance.emissive.multiplyScalar(1.1);
232:       if (instance.emissive) instance.userData.baseEmissive = instance.emissive.clone();
233:       return instance;
234:     };
235:     part.material = Array.isArray(part.material) ? part.material.map(cloneMaterial) : cloneMaterial(part.material);
236:   });
237:   replacement.updateWorldMatrix(true, true);
238:   const bounds = new THREE.Box3().setFromObject(replacement);
239:   const size = bounds.getSize(new THREE.Vector3());
240:   if (!Number.isFinite(size.y) || size.y < 0.1) return false;
241:   const center = bounds.getCenter(new THREE.Vector3());
242:   const scale = (1.65 * zombie.variant.modelScale) / size.y;
243:   replacement.scale.setScalar(scale);
244:   replacement.position.set(-center.x * scale, -bounds.min.y * scale, -center.z * scale);
245:   const root = new THREE.Group();
246:   root.add(replacement);
247:   addZombieHealthBar(zombie, root);
248:   if (zombie.model) {
249:     scene.remove(zombie.model);
250:     zombie.model.traverse((part) => { if (part.geometry) part.geometry.dispose(); });
251:   }
252:   scene.add(root);
253:   zombie.model = root;
254:   zombie.limbs = [];
255:   zombie.mixer = new THREE.AnimationMixer(replacement);
256:   if (zombieAsset.clips.length) {
257:     zombie.action = zombie.mixer.clipAction(zombieAsset.clips[0]);
258:     zombie.action.setLoop(THREE.LoopRepeat, Infinity);
259:     zombie.action.play();
260:   }
261:   syncEntity(zombie);
262:   return true;
263: }
264: function loadZombieAsset() {
265:   zombieAsset.ready = new Promise((resolve) => {
266:     if (!THREE.GLTFLoader) {
267:       zombieAsset.failed = true;
268:       console.warn('GLTFLoader unavailable; using procedural zombies.');
269:       resolve(false);
270:       return;
271:     }
272:     const loader = new THREE.GLTFLoader();
273:     loader.load('public/models/zombie.glb', (gltf) => {
274:       zombieAsset.root = gltf.scene;
275:       zombieAsset.clips = gltf.animations || [];
276:       for (const zombie of world.zombies) applyZombieAsset(zombie);
277:       resolve(true);
278:     }, undefined, (error) => {
279:       zombieAsset.failed = true;
280:       console.warn('Zombie model failed to load; using procedural fallback.', error);
281:       resolve(false);
282:     });
283:   });
284:   return zombieAsset.ready;
