302: function updateZombieHealthBar(zombie) {
303:   if (!zombie.healthBar) return;
304:   const ratio = clamp(zombie.hp / zombie.maxHp, 0, 1);
305:   const { fill, width } = zombie.healthBar;
306:   fill.visible = ratio > 0;
