308:   fill.position.x = -(width * (1 - ratio)) / 2;
309:   fill.material.color.setHex(zombie.isBoss ? 0xff4b5c : ratio > 0.55 ? 0x75d477 : ratio > 0.25 ? 0xe7bd4c : 0xe34e4e);
310: }
