import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', e => errors.push(e.message))
await page.route('**/game.js', async route => {
  const response = await route.fetch()
  const source = await response.text()
  await route.fulfill({ response, body: source + '\nwindow.__test = { world, defeatZombie, showUpgradeChoices, finishGame };\n' })
})
try {
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__test && window.THREE, { timeout: 45000 })
  await page.locator('#startButton').click()
  await page.waitForFunction(() => window.__test.world.running && !window.__test.world.paused)
  const start = await page.evaluate(() => ({ running: __test.world.running, wave: __test.world.wave, zombies: __test.world.zombies.length }))
  await page.keyboard.press('Escape')
  const pauseOpen = await page.locator('#pauseOverlay').isVisible()
  await page.keyboard.press('Escape')
  const resumed = await page.evaluate(() => !__test.world.paused)
  await page.evaluate(() => { __test.world.elapsed = 119.99 })
  await page.waitForFunction(() => __test.world.wave === 5 && __test.world.zombies.some(z => z.isBoss), { timeout: 5000 })
  const bossState = await page.evaluate(() => {
    const boss = __test.world.zombies.find(z => z.isBoss)
    return { wave: __test.world.wave, bossHp: boss?.hp, bossMaxHp: boss?.maxHp, bossCount: __test.world.zombies.filter(z => z.isBoss).length }
  })
  await page.evaluate(() => {
    const i = __test.world.zombies.findIndex(z => z.isBoss)
    __test.defeatZombie(__test.world.zombies[i], i)
  })
  const rewardModalOpen = await page.locator('#bossRewardOverlay').isVisible()
  await page.keyboard.press('Escape')
  const rewardStillOpenOnPauseKey = await page.locator('#bossRewardOverlay').isVisible()
  const rewardChoices = await page.locator('#bossRewardChoices button').count()
  await page.locator('#bossRewardChoices button').first().click()
  const rewardResolved = await page.evaluate(() => ({ paused: __test.world.paused, hidden: document.querySelector('#bossRewardOverlay').classList.contains('hidden') }))
  await page.evaluate(() => { __test.world.player.xp = 0; __test.showUpgradeChoices() })
  const upgradeModalOpen = await page.locator('#upgradeOverlay').isVisible()
  await page.locator('#upgradeChoices button').first().click()
  const upgradeResolved = await page.evaluate(() => ({ paused: __test.world.paused, hidden: document.querySelector('#upgradeOverlay').classList.contains('hidden') }))
  await page.evaluate(() => __test.finishGame())
  await page.locator('#restartButton').click()
  await page.waitForFunction(() => __test.world.running && !__test.world.gameOver && document.querySelector('#bossRewardOverlay').classList.contains('hidden'))
  const restartResolved = await page.evaluate(() => ({ running: __test.world.running, gameOver: __test.world.gameOver, rewardHidden: document.querySelector('#bossRewardOverlay').classList.contains('hidden'), upgradeHidden: document.querySelector('#upgradeOverlay').classList.contains('hidden') }))
  console.log(JSON.stringify({ start, pauseOpen, resumed, bossState, rewardModalOpen, rewardStillOpenOnPauseKey, rewardChoices, rewardResolved, upgradeModalOpen, upgradeResolved, restartResolved, errors }, null, 2))
} finally {
  await browser.close()
}

